<script setup lang="ts">
import {managerFetch} from '../../../../../live-management/manager-api.mjs';
const fetch=(url:string, options?:RequestInit)=>managerFetch('dns-manager',url,options);

import * as Vue from 'vue';import {component} from '../../../../../rancher-common-ui/client/index.mjs';const ScheduleLayout=component('ScheduleLayout',Vue);const StorageSummary=component('StorageSummary',Vue);
import { displaySettings } from '../data/display-settings';
import { onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { captureScheduleSource, loadSchedule, saveSchedule, runSchedule, scheduleState, snapshotStorage, storageError, refreshSnapshotStorage } from '../data/snapshot-schedule';
import {askSnapshotOptions} from '../data/unlock-backup';
const controller=new AbortController();onBeforeUnmount(()=>controller.abort());
import {formatExhaustion as spaceDate} from '../../../../../preview-data/storage-display.mjs';
import { formatSize } from '../config/file-size.mjs';
import { storedSnapshots, refreshSnapshots } from '../data/stored-snapshots';
import HelpTip from './HelpTip.vue';
const inventory={namespaces:['dns-system']};
import { useFormGuard } from '../data/form-guard';
watch([storedSnapshots,scheduleState], () => { void refreshSnapshotStorage(); });
const cleanup = ref<any>(null);const cleanupForm=reactive({interval:1,unit:'days',retention:30,retentionUnit:'days'});
async function loadCleanup(){const response=await fetch('/api/snapshot-cleanup');if(!response.ok)throw new Error('Cleanup scheduling is unavailable.');cleanup.value=await response.json();Object.assign(cleanupForm,{interval:cleanup.value.interval,unit:cleanup.value.unit,retention:cleanup.value.retention,retentionUnit:cleanup.value.retentionUnit});}
async function saveCleanup(enabled=cleanup.value?.enabled||false){busy.value=true;message.value='';try{const response=await fetch('/api/snapshot-cleanup',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...cleanupForm,enabled})});if(!response.ok)throw new Error('Check cleanup interval and retention.');cleanup.value=await response.json();message.value='Cleanup Schedule Saved.';guard.clean();}catch(e){message.value=e instanceof Error?e.message:'Save failed.';}finally{busy.value=false;}}
async function runCleanup(){busy.value=true;try{const response=await fetch('/api/snapshot-cleanup/run',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error('Cleanup failed.');cleanup.value=await response.json();await refreshSnapshots();await refreshSnapshotStorage();message.value=`Cleanup Completed: ${cleanup.value.lastDeleted} Snapshots Removed.`;}catch(e){message.value=e instanceof Error?e.message:'Cleanup failed.';}finally{busy.value=false;}}
const form = reactive({ interval: 1, unit: 'days', namespace: '' });
const busy = ref(false); const message = ref(''); const loaded = ref(false);
onMounted(async () => { try { const state = await loadSchedule(); Object.assign(form, { interval: state.interval, unit: state.unit, namespace: state.scope?.namespace || '' }); await loadCleanup(); await refreshSnapshotStorage(); loaded.value = true; guard.clean(); } catch (error) { message.value = error instanceof Error ? error.message : 'Schedule unavailable.'; } });
async function save(enabled = scheduleState.value?.enabled || false) {
  busy.value = true; message.value = '';
  try {
    if(!enabled&&scheduleState.value?.enabled){await saveSchedule({...form,enabled});}
    else{const options=await askSnapshotOptions(false,controller.signal,true);try{await saveSchedule({...form,enabled,...options,current:captureScheduleSource(form.namespace)});}finally{options.password='';}} message.value = '';  guard.clean(); } catch (error) { message.value = error instanceof Error ? error.message : 'Save failed.'; } finally { busy.value = false; }
}
async function run() { busy.value = true; message.value = ''; try { let options=await askSnapshotOptions(false,controller.signal);try{await runSchedule(form.namespace,options.password,options.includeSecrets);}finally{options.password='';} await refreshSnapshots(); message.value = 'Snapshot ZIP Saved.'; } catch (error) { message.value = error instanceof Error ? error.message : 'Capture failed.'; } finally { busy.value = false; } }
const guard = useFormGuard('history', () => 'Snapshot Schedule', () => ({form:{...form},cleanup:{...cleanupForm}}), state => {Object.assign(form,state.form);Object.assign(cleanupForm,state.cleanup);}, () => loaded.value);
</script>
<template>
  <ScheduleLayout><section class="snapshot-schedule"><div class="schedule-heading"><h3>Automatic Snapshot Schedule <HelpTip label="Automatic Snapshot Schedule Help" text="The hosting service runs the saved scope even with the browser closed. The preview uses saved inspection data, not fresh cluster observations. Save Schedule and Enable ask whether to include Secrets. Protected schedules retain their password in a backend Secret so automatic runs and ZIP recovery can use it. Run Now asks for options separately. ZIPs contain a recovery index and manifests. Save Schedule persists settings; Enable starts scheduling."/></h3><span class="schedule-badge" :class="scheduleState ? scheduleState.enabled ? 'enabled' : 'disabled' : 'unknown'">{{scheduleState ? scheduleState.enabled ? 'Enabled' : 'Disabled' : 'Unavailable'}}</span></div><div class="schedule-fields"><label class="schedule-number">Every<input v-model.number="form.interval" type="number" min="1" max="365"></label><label class="schedule-unit">Unit<select v-model="form.unit"><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label><label class="schedule-scope">Scope<select v-model="form.namespace"><option value="">All DNS Configuration</option><option v-for="namespace in inventory.namespaces" :key="namespace">{{ namespace }}</option></select></label><div class="schedule-actions"><button type="button" :disabled="busy || !loaded" @click="save()">Save Schedule</button><button type="button" :disabled="busy || !loaded" @click="save(!scheduleState?.enabled)">{{ scheduleState?.enabled ? 'Disable' : 'Enable' }}</button><button type="button" :disabled="busy || !loaded" @click="run">Run Now</button></div></div><p>Next Snapshot: {{ scheduleState?.nextRun ? new Date(scheduleState.nextRun).toLocaleString() : 'Not Scheduled' }}</p></section><section class="snapshot-schedule"><div class="schedule-heading"><h3>Automatic Snapshot Cleanup <HelpTip label="Automatic Snapshot Cleanup Help" text="Cleanup removes backups older than retention while preserving the newest backup of each known scope and configuration item. Save Schedule persists retention settings; Enable starts periodic cleanup; Run Now performs cleanup immediately."/></h3><span class="schedule-badge" :class="cleanup ? cleanup.enabled ? 'enabled' : 'disabled' : 'unknown'">{{cleanup ? cleanup.enabled ? 'Enabled' : 'Disabled' : 'Unavailable'}}</span></div><div class="schedule-fields"><label class="schedule-number">Every<input v-model.number="cleanupForm.interval" type="number" min="1" max="365"></label><label class="schedule-unit">Unit<select v-model="cleanupForm.unit"><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label><label class="schedule-number">Keep For<input v-model.number="cleanupForm.retention" type="number" min="1" max="365"></label><label class="schedule-unit">Retention Unit<select v-model="cleanupForm.retentionUnit"><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label><div class="schedule-actions"><button type="button" :disabled="busy||!loaded" @click="saveCleanup()">Save Schedule</button><button type="button" :disabled="busy||!loaded" @click="saveCleanup(!cleanup?.enabled)">{{ cleanup?.enabled ? 'Disable' : 'Enable' }}</button><button type="button" :disabled="busy||!loaded" @click="runCleanup">Run Now</button></div></div><p>Next Delete: {{ cleanup?.nextRun ? new Date(cleanup.nextRun).toLocaleString() : 'Not Scheduled' }}</p></section><StorageSummary :available="snapshotStorage?.effectiveAvailableBytes!=null?`${formatSize(snapshotStorage.effectiveAvailableBytes)} / ${formatSize(snapshotStorage.effectiveTotalBytes)}`:'Unavailable — Storage Quota Unknown'" :largest="snapshotStorage?formatSize(snapshotStorage.largestSnapshotBytes):'Unavailable'" :run-out="spaceDate(snapshotStorage)" :run-out-title="snapshotStorage?.runOutAt||snapshotStorage?.reason" :mock="snapshotStorage?.mockCapacity"/><p v-if="message||scheduleState?.lastError||cleanup?.lastError||storageError" class="schedule-errors" role="status">{{message||scheduleState?.lastError||cleanup?.lastError||storageError}}</p></ScheduleLayout>
</template>
